// Validate and normalize incoming alarm
// The Webhook node puts the POSTed JSON under .body
const body = $input.first().json.body ?? $input.first().json;

const required = ['device_name', 'alarm_type', 'severity'];
const validSeverities = ['Critical', 'Major', 'Minor', 'Warning', 'Info'];
const validTypes = ['LOS', 'LOF', 'High BER', 'Interface Down', 'Device Unreachable', 'Optical Power Low', 'Card Failure'];

// Validation
for (const field of required) {
  if (!body[field]) {
    throw new Error(`Validation failed: missing required field '${field}'`);
  }
}

if (!validSeverities.includes(body.severity)) {
  throw new Error(`Invalid severity '${body.severity}'. Must be one of: ${validSeverities.join(', ')}`);
}

if (!validTypes.includes(body.alarm_type)) {
  // Allow through with warning — don't reject unknown types
  console.warn(`Unknown alarm_type: ${body.alarm_type}`);
}

// Sanitize description to prevent prompt injection
const sanitizeText = (text) => {
  if (!text) return text;
  return String(text)
    .replace(/[<>]/g, '')
    .replace(/\bignore\b.{0,50}\binstructions\b/gi, '[FILTERED]')
    .replace(/\bsystem\s*prompt\b/gi, '[FILTERED]')
    .slice(0, 500);
};

// Normalize
const normalized = {
  alarm_id:        body.alarm_id || '',   // empty -> generated by Postgres in 'Upsert Alarm'
  device_name:     String(body.device_name).slice(0, 100),
  device_id:       body.device_id || null,
  alarm_type:      String(body.alarm_type).slice(0, 100),
  severity:        body.severity,
  interface_name:  body.interface_name ? String(body.interface_name).slice(0, 100) : null,
  description:     sanitizeText(body.description) || `${body.alarm_type} alarm on ${body.device_name}`,
  alarm_timestamp: body.alarm_timestamp || new Date().toISOString(),
  alarm_source:    body.alarm_source || 'webhook',
  raw_payload:     JSON.stringify(body.raw_payload || body),
  validation_ok:   true,
};

return [{ json: normalized }];

// Same device + alarm type already being handled within the last 5 minutes?
const alarm = $('Upsert Alarm').first().json;
const duplicateOf = $input.first().json.duplicate_of_alarm_id || null;

return [{
  json: {
    ...alarm,
    is_duplicate: !!duplicateOf,
    duplicate_of_alarm_id: duplicateOf,
    proceed_with_investigation: !duplicateOf,
  }
}];

// Consolidate all specialist results into final incident
const classification = $('Call: Alarm Classification').first()?.json || {};
const rca           = $('Call: Root Cause Analysis').first()?.json || {};
const topology      = $('Call: Topology Impact').first()?.json || {};
const remediation   = $('Call: Remediation & Report').first()?.json || {};
const alarm         = $('Prepare Agent Input').first().json;

// Quality check — ensure we have minimum required fields
const hasClassification = classification.alarm_category || classification.severity;
const hasRCA            = rca.probable_root_cause;
const hasRemediation    = remediation.recommended_actions;

const incident = {
  incident_id:             alarm.incident_id,
  alarm_id:                alarm.alarm_id,
  incident_title:          `${alarm.severity} ${alarm.alarm_type} Alarm on ${alarm.device_name} — ${rca.probable_root_cause || 'Under Investigation'}`.slice(0, 500),
  severity:                classification.severity || alarm.severity,
  probable_root_cause:     rca.probable_root_cause || 'Under investigation',
  supporting_evidence:     JSON.stringify(rca.supporting_evidence || []),
  alternative_causes:      JSON.stringify(rca.alternative_causes || []),
  confidence_estimate:     typeof rca.confidence === 'number' ? Math.min(Math.max(rca.confidence, 0), 1) : null,
  estimated_repair_time:   rca.estimated_repair_time_hours != null ? `${rca.estimated_repair_time_hours} hours` : null,
  affected_devices:        JSON.stringify(topology.affected_nodes || [alarm.device_name]),
  affected_services:       JSON.stringify(topology.affected_services || []),
  impact_level:            topology.impact_level || 'Unknown',
  recommended_actions:     JSON.stringify(remediation.recommended_actions || []),
  requires_human_approval: true,
  incident_status:         'open',
  classification_result:   JSON.stringify(classification),
  rca_result:              JSON.stringify(rca),
  topology_result:         JSON.stringify(topology),
  remediation_result:      JSON.stringify(remediation),
  full_report:             remediation.incident_report || '',
  quality_ok:              hasClassification && hasRCA && hasRemediation,
};

return [{ json: { incident, alarm } }];

// Common input for the three specialist agents
const a = $('Check Duplicate').first().json;
return [{
  json: {
    alarm_id:        a.alarm_id,
    incident_id:     $input.first().json.incident_id,
    device_name:     a.device_name,
    device_id:       a.device_id,
    alarm_type:      a.alarm_type,
    severity:        a.severity,
    interface_name:  a.interface_name,
    description:     a.description,
    alarm_timestamp: a.alarm_timestamp,
  }
}];

// NETOPS-05 needs the alarm context plus all three specialist results
const ctx = $('Prepare Agent Input').first().json;
return [{
  json: {
    ...ctx,
    classification_result: JSON.stringify($('Call: Alarm Classification').first().json),
    rca_result:            JSON.stringify($('Call: Root Cause Analysis').first().json),
    topology_result:       JSON.stringify($('Call: Topology Impact').first().json),
  }
}];
